css:
/* In-game typefaces (from the client via the Data Explorer): Exocet Blizzard OT Medium = item/skill names, PT Serif = tooltip body */
@font-face { font-family: 'D4 Exocet'; src: url(https://d4guides.gg/assets/fonts/d4-exocet-medium.woff2) format('woff2'); font-weight: 400; font-display: swap; }
@font-face { font-family: 'D4 PT Serif'; src: url(https://d4guides.gg/assets/fonts/d4-ptserif-regular.woff2) format('woff2'); font-weight: 400; font-style: normal; font-display: swap; }
@font-face { font-family: 'D4 PT Serif'; src: url(https://d4guides.gg/assets/fonts/d4-ptserif-italic.woff2) format('woff2'); font-weight: 400; font-style: italic; font-display: swap; }
@font-face { font-family: 'D4 PT Serif'; src: url(https://d4guides.gg/assets/fonts/d4-ptserif-bold.woff2) format('woff2'); font-weight: 700; font-style: normal; font-display: swap; }
/* Tooltips im Spiel-Look (Explorer-Umbau Stufe 3) — ported from the Data Explorer's itemtip.css / styles.css (S15 screenshots, measured at
   the game's 505 px panel). Everything is namespaced under .d4tt-chrome so the classic tooltip (tooltip.css, tooltip.php) stays untouched.
   Sizes inside the panel are container units (1cqw = panel width / 100): the game's proportions at any width. */
.item-tooltip:has(> .d4tt-chrome) { background: none; border: 0; box-shadow: none; max-width: none; min-width: 0; padding: 0; border-radius: 0; }
.d4tt-chrome { position: relative; width: 400px; max-width: min(100vw - 16px, 400px); box-sizing: border-box; container-type: inline-size;
  --d4tt-body: 'D4 PT Serif', 'PT Serif', Georgia, serif; --d4tt-head: 'D4 Exocet', 'OldFenris', serif;
  filter: drop-shadow(0 8px 24px rgba(0,0,0,.85)); }
.d4tt-content { position: relative; z-index: 3; padding: 6cqw 5cqw 5.5cqw 6.3cqw; font-family: var(--d4tt-body); font-size: 4.75cqw; line-height: 1.25; color: #b4aa9c;
  text-shadow: 0 0 2px rgba(0,0,0,.85), 1px 1px 1px rgba(0,0,0,.6); word-wrap: break-word; }
/* 9-slice layers: base window (corners 76 px × .5), rarity panel (128 × .6), ornate frame (143 × .5) */
.d4tt-9s { position: absolute; inset: 0; display: grid; grid-template-columns: var(--c) 1fr var(--c); grid-template-rows: var(--c) 1fr var(--c); pointer-events: none; z-index: 1; }
.d4tt-9s i { display: block; background-repeat: no-repeat; background-size: 100% 100%; }
.d4tt-9s-base { --c: 9.5cqw; }            /* 38 px at 400 */
.d4tt-9s-rarity { --c: 19.2cqw; z-index: 2; } /* 77 px at 400 */
.d4tt-9s-ornate { --c: 18cqw; z-index: 4; inset: -2.5cqw; }
/* The nine pieces of a layer must meet on whole pixels: the rarity panels are translucent (alpha ~35 %), so a hairline gap between two pieces
   shows the dark window below (black stripe) and any overlap doubles the tint (light stripe) — both seen on 27.09.2026 with the fractional
   cqw sizes (19.2cqw of the 476 px paragon card = 91.4 px). Corner sizes, the ornate overhang and a squeezed card width are rounded to whole
   pixels here; tooltip.js snapChrome() rounds the content-driven height — like the explorer's NineSlice (integer pieces + snapped rows). */
@supports (width: round(1.5px, 1px)) {
  .d4tt-9s-base { --c: round(9.5cqw, 1px); }
  .d4tt-9s-rarity { --c: round(19.2cqw, 1px); }
  .d4tt-9s-ornate { --c: round(18cqw, 1px); inset: calc(-1 * round(2.5cqw, 1px)); }
}
.d4tt-9s-base .d4tt-9s-center { background-size: 100% 100%; }
.d4tt-9s-rarity .d4tt-9s-center { background-size: 100% 100%; }
.d4tt-9s-ornate .d4tt-9s-center { background: none !important; }
/* header */
.d4tt .tt-head { position: relative; display: block; margin: 0; padding: 0; min-height: 12cqw; }
.d4tt .it-headtext { max-width: 62cqw; }
.d4tt .it-image { position: absolute; top: -3cqw; right: -2cqw; width: 26cqw; height: 36cqw; object-fit: contain; object-position: top center; z-index: 2; pointer-events: none;
  filter: drop-shadow(0 2px 4px rgba(0,0,0,.7)); }
.d4tt .tt-title { font-family: var(--d4tt-head); font-size: 6.2cqw; line-height: 1.11; letter-spacing: -.05em; font-weight: 400; text-transform: uppercase; color: #e9e9e9;
  text-shadow: 0 0 1px #000, 1px 1px 1px rgba(0,0,0,.8), 0 0 3px rgba(0,0,0,.6); hyphens: manual; }
.d4tt .tt-title.q-magic { color: #7b7cf5; } .d4tt .tt-title.q-rare { color: #eaec0a; } .d4tt .tt-title.q-legendary { color: #f78005; }
.d4tt .tt-title.q-unique, .d4tt .tt-title.q-mythic { color: #d9a879; } .d4tt .tt-title.q-set { color: #2ef20d; }
.d4tt .tt-sub { font-size: 4.75cqw; line-height: 1.38; margin-top: 1.6cqw; color: #c7c7c7; }
.d4tt .tt-sub.q-magic { color: #6969d2; } .d4tt .tt-sub.q-rare { color: #c8ca08; } .d4tt .tt-sub.q-legendary { color: #d46d05; }
.d4tt .tt-sub.q-unique, .d4tt .tt-sub.q-mythic { color: #ba8f67; } .d4tt .tt-sub.q-set { color: #27d10a; }
.d4tt .tt-ip { font-size: 4.75cqw; line-height: 1.38; color: #b4aa9c; }
/* dividers: header ornament (DividerArt) and the centre "<◇>" line, 654×19 art over the content width */
.d4tt .it-div { height: auto; width: calc(100% + 1.6cqw); aspect-ratio: 654 / 19; background: url(https://d4guides.gg/assets/img/ui/tooltip/divider_head.webp) left center / 100% 100% no-repeat; margin: 1.8cqw 0 2.4cqw -1.6cqw; }
.d4tt .it-div-center { background-image: url(https://d4guides.gg/assets/img/ui/tooltip/divider_center.webp); margin: 1.8cqw 0 2.2cqw -1.6cqw; }
.d4tt .it-div:not([style]) { /* fallback until the divider art is on the site: thin ornament line */ }
/* stat / power lines: bullet centred at 2.2 % of W, text at 6.5 % */
.d4tt .it-base, .d4tt .it-stats, .d4tt .it-powers { display: flex; flex-direction: column; margin: 0; }
.d4tt .stat-line { display: flex; align-items: flex-start; line-height: 1.25; margin: 0 0 1.05cqw; color: #b4aa9c; }
.d4tt .stat-text { flex: 1; min-width: 0; }
.d4tt .affix-glyph { flex: none; width: .39em; height: .39em; object-fit: contain; margin: calc((1.25em - .39em) / 2) calc(4.3cqw - .2em) 0 calc(2.2cqw - .2em); filter: brightness(.7); }
.d4tt .affix-glyph.ag-dot { border-radius: 50%; background: #797a74; }
.d4tt .ag-legendarystar { width: .95em; height: .95em; margin: calc((1.25em - .95em) / 2) calc(4.3cqw - .48em) 0 calc(2.2cqw - .48em); filter: none; }
.d4tt .ag-uniquestar, .d4tt .ag-mythicstar { width: .86em; height: .86em; margin: calc((1.25em - .86em) / 2) calc(4.3cqw - .43em) 0 calc(2.2cqw - .43em); filter: brightness(.74); }
.d4tt .ag-mythicstar { filter: none; }
.d4tt .power-line { color: #b4aa9c; }
.d4tt .stat-line.unknown .gt-value.unknown { color: #ba100d; }
/* game-text colours (sampled) */
.d4tt .gt { white-space: pre-wrap; }
.d4tt .gt-value { color: inherit; font-weight: 400; }
.d4tt .gt-mark, .d4tt .gt-mult { color: #808080; font-weight: 400; }
.d4tt .gt-pctmark { color: #8c8c8c; font-weight: 400; }   /* weapon-damage percentage behind the absolute value, like the game's advanced tooltip "126.756 [382%]" */
.d4tt .gt-c_number { color: #d9a962; } .d4tt .gt-c_random { color: #ababf6; } .d4tt .gt-c_important { color: #dcd9d3; }
.d4tt .gt-c_label, .d4tt .gt-c_gold { color: #b79e7a; } .d4tt .gt-c_gray { color: #686868; } .d4tt .gt-c_highlight { color: #bf6a2c; }
.d4tt .gt-c_quality { color: #8582f7; } .d4tt .gt-c_rune { color: #f3b985; } .d4tt .gt-c_RuneCondition, .d4tt .gt-c_runecondition { color: #ce9110; }
.d4tt .gt-c_RuneEffect, .d4tt .gt-c_runeeffect { color: #b140cb; } .d4tt .gt-c_set { color: #2ef30d; } .d4tt .gt-c_advanced { color: #808080; }
.d4tt .gt-c_red { color: #ba100d; } .d4tt .gt-c_green { color: #4fbf5a; } .d4tt .gt-c_white { color: #e9e9e9; } .d4tt .gt-c_resource { color: #7b7cf5; }
.d4tt .gt-c_unique { color: #d9a879; } .d4tt .gt-c_legendary { color: #f78005; } .d4tt .gt-c_mythic { color: #d9a879; } .d4tt .gt-c_keyword { color: #dcd9d3; }
.d4tt .gt-u { text-decoration: underline solid; text-underline-offset: .14em; text-decoration-thickness: 1px; color: #dcd9d3; }
.d4tt .gt-b { font-weight: 700; } .d4tt .gt-i { font-style: italic; }
.d4tt .gt-if, .d4tt .gt-else { display: inline; } .d4tt .gt-else::before, .d4tt .gt-else::after { content: none; }
.d4tt .gt-icon-img { height: .8em; width: auto; vertical-align: -.1em; margin: 0 .15em; }
.d4tt .gt-icon { color: #b79e7a; } .d4tt .gt-icon::before { content: '◆'; font-size: .6em; vertical-align: .1em; }
.d4tt .gt-icon[data-icon="bullet"]::before { content: '•'; } .d4tt .gt-icon[data-icon="arrow"]::before { content: '→'; }
/* sections below the stats */
.d4tt .tt-section, .d4tt .it-socket, .d4tt .it-set { margin-top: 2.4cqw; }
.d4tt .tt-label { color: #b79e7a; font-size: 4.2cqw; letter-spacing: .04em; margin-bottom: .8cqw; }
.d4tt .it-set-name, .d4tt .q-set { color: #2ef30d; }
.d4tt .it-flavor { margin-top: 2.6cqw; color: #8a7c68; font-size: 4.3cqw; line-height: 1.3; }
.d4tt .it-footer { margin-top: 2.6cqw; text-align: right; color: #b4aa9c; font-size: 4.4cqw; line-height: 1.35; }
.d4tt .it-class-icon { height: 1.2em; width: auto; vertical-align: middle; margin: 0 .2em; }
.d4tt .d4tt-extra { margin-top: 2.6cqw; padding-top: 2cqw; border-top: 1px solid rgba(183,158,122,.25); font-size: 4.2cqw; color: #9c8f7a; }
/* ---- skill tooltip (explorer PowerCard / game 211703, 102829): icon plate hanging over the top edge, centred name in the body face,
   "RANG x/15" banner on the section-header art, tag pills, full-width divider, description, "Nächster Rang", modifiers banner + list,
   right-aligned footer divider with damage type / weapon requirement; keyword boxes under the frame.
   Proportions of the game (explorer skilltree.css "gamewin", measured at native 1440p on 102829/211703): body 538 px = 100cqw, 1 px = .186cqw —
   text 22/30 px, title 32.5 px, banner 22.5 px (bar 37 px), tag pills 43 px / 23 px, icon plate 131 px at -70 px, content padding 0 27 26 31 px. */
.d4tt-chrome-skill { margin-top: 64px; }   /* room for the icon plate above the panel (mobile sheet clips overflow) */
/* the plate and the glyph medallion sit in front of the ornate frame (game 211703): lift the content layer above the frame layer */
.d4tt-chrome-skill .d4tt-content, .d4tt-chrome-generic:has(.d4tt-glyph) .d4tt-content { z-index: 5; }
.d4tt-chrome-skill .d4tt-content { padding: 0 5.02cqw 4.83cqw 5.76cqw; font-size: 4.09cqw; line-height: 1.364; }
.d4tt-skill { position: relative; }
.d4tt-skill .stt-plate { position: absolute; left: 50%; top: -13.01cqw; transform: translateX(-50%); width: 24.35cqw; height: 24.35cqw; z-index: 5; pointer-events: none; }
.d4tt-skill .skill-icon-wrap { display: block; width: 100%; height: 100%; background: url(https://d4guides.gg/assets/img/ui/tooltip/skill_icon_frame.webp) center / 100% 100% no-repeat; filter: drop-shadow(0 3px 6px rgba(0,0,0,.7)); }
.d4tt-skill .stt-icon { display: block; width: 100%; height: 100%; object-fit: contain; padding: 23%; box-sizing: border-box; }
.d4tt-skill .stt-title { font-family: var(--d4tt-body); text-transform: none; letter-spacing: 0; text-align: center; color: #dcd7cd; font-size: 6.04cqw; line-height: 1.2; padding-top: 11.71cqw; overflow-wrap: anywhere; }
.d4tt .stt-banner { background: url(https://d4guides.gg/assets/img/ui/tooltip/section_header.webp) center / 100% 100% no-repeat; text-align: center; text-transform: uppercase; letter-spacing: .06em; font-family: 'OldFenris', var(--d4tt-head); font-size: 4.45cqw; line-height: 1.2; padding: 1.2cqw 2.4cqw; margin: 1.6cqw -.5cqw 0; color: #e8e2d6; }
.d4tt-skill .stt-banner { font-size: 4.18cqw; line-height: 1.11; padding: 1.115cqw 2.23cqw; margin: 1.49cqw 0 0; }
.d4tt .stt-banner .gt-c_white { color: #f2ede3; } .d4tt .stt-banner .gt-c_magic { color: #7b7cf5; }
.d4tt .stt-tags { display: flex; flex-wrap: wrap; gap: 1.49cqw; margin: 2.42cqw 0 0; } .d4tt .stt-banner + .stt-tags { margin-top: 2.04cqw; }   /* 211703: pills 11 px under the rank bar */
.d4tt .stt-pill { display: inline-block; height: 7.99cqw; line-height: 7.99cqw; padding: 0 2.6cqw; font-size: 4.275cqw; color: #dac49f; background: #202020; box-shadow: inset 0 0 0 1px #383738; }
.d4tt .stt-pill.stt-cat { background: #012000; box-shadow: inset 0 0 0 1px #073a04; }
.d4tt .stt-divider { height: 3.53cqw; background: url(https://d4guides.gg/assets/img/ui/tooltip/divider_skill_top.webp) center / 100% 100% no-repeat; }
.d4tt .stt-divider.top { margin: 1.49cqw -.74cqw .56cqw; }
.d4tt .stt-divider.foot { background-image: url(https://d4guides.gg/assets/img/ui/tooltip/divider_skill_foot.webp); width: 52%; margin: .93cqw 0 -.56cqw auto; }
.d4tt-skill .stt-desc, .d4tt-skill .stt-next, .d4tt-skill .stt-mods { color: #b4aa9c; line-height: 1.364; }
.d4tt-skill .stt-desc { margin-top: .19cqw; }
.d4tt-skill .stt-desc .gt-c_number { color: #d9a962; } .d4tt-skill .gt-c_resource { color: #eaeb6d; } .d4tt-skill .gt-c_important { color: #efebe3; } .d4tt-skill .gt-c_label { color: #b79e7a; }
.d4tt-skill .stt-next { margin-top: 0; } .d4tt-skill .stt-next > div { display: block; }
.d4tt-skill .stt-next .gt-icon-bullet, .d4tt-skill .stt-desc .gt-icon-bullet { height: 1em; vertical-align: -.15em; margin: 0 .1em 0 0; } .d4tt-skill .gt-icon-arrow { height: .85em; vertical-align: -.08em; margin: 0 .15em; }
.d4tt-skill .stt-mods { list-style: none; padding: 0; margin: 1.2cqw 0 0; }
.d4tt-skill .stt-mods li { position: relative; padding-left: 5cqw; margin: 0; }
.d4tt-skill .stt-mods li::before { content: ''; position: absolute; left: 0; top: .18em; width: 1em; height: 1em; background: url(https://d4guides.gg/assets/img/ui/fonticons/bullet.webp) center / contain no-repeat; }
.d4tt-skill .stt-modof { text-align: center; color: #c4bdb2; margin: 1cqw 0 0; } .d4tt-skill .stt-modrank { display: none; }   /* the planner allows one point per modifier; "Rank 1/3" misled (user decision 27.09., BRP-07) */
.d4tt-skill .stt-foot { text-align: right; color: #9c9c9c; line-height: 1.59; }
.d4tt-skill .stt-foot .stt-dmg .gt-icon-img { height: 1.2em; vertical-align: -.28em; margin-right: 1.6cqw; }
.d4tt-skill .stt-state { color: #ba100d; }
.d4tt-skill .gt-u { color: #dcd9d3; text-underline-offset: .18em; }
/* Warlock soul shard: "Grants the Summon … skill" line with the skill icon under the description */
.d4tt-skill .stt-grants { display: flex; align-items: center; gap: 2.4cqw; margin-top: 2.4cqw; color: #b4aa9c; line-height: 1.36; }
.d4tt-skill .stt-grant-icon { flex: none; width: 11cqw; height: 11cqw; object-fit: contain; }
/* seasonal power (explorer SeasonTooltip): square icon box with the shard frame, type line, "Max Rank" banner, acquisition text in italics */
.d4tt-season .skill-icon-wrap { background-size: 100% 100%; filter: drop-shadow(0 3px 6px rgba(0,0,0,.7)); }
.d4tt-season .stt-icon { padding: 16%; }
.d4tt-season .stt-sub { text-align: center; color: #e9e9e9; font-size: 4.35cqw; line-height: 1.2; margin-top: 2.4cqw; }
.d4tt-season .stt-flavor { margin-top: 1.25em; font-style: italic; color: #808080; font-size: 4.1cqw; line-height: 1.38; }
.d4tt-season .stt-req-season { margin-top: .9em; } .d4tt-season .stt-req-season .gt-c_red { color: #ba100d; }
.d4tt-season .stt-desc .gt-c_random { color: #ababf6; } .d4tt-season .stt-desc .gt-value { color: inherit; }
/* icon box as the explorer's SeasonTooltip (season.css .season-iconbox: 72 px on the 400 px panel, top edge 38 px above the panel, centred on the
   panel): dark box with Power_Frame 2714295658 as nine-slice, the power's inventory icon (shield + glyph in one image) at 12 % inset */
.d4tt-season .stt-seasonbox { top: -12.5cqw; left: calc(50% - .65cqw); width: 18cqw; height: 18cqw; box-sizing: border-box; background: #0e100f;
  border: 1.25cqw solid transparent; border-image: url(https://d4guides.gg/assets/img/ui/tooltip/season_power_frame.webp) 18 fill / 1.25cqw stretch; }
.d4tt-season .stt-seasonbox-img { position: absolute; inset: 12%; width: 76%; height: 76%; object-fit: contain; }
.d4tt-season .stt-seasonbox ~ .stt-title { padding-top: 8.6cqw; }
/* typography as the explorer's SeasonTooltip in game fonts (season.css, measured on its 400 px panel, 1cqw = 4 px): body PT Serif 15.3 px / 1.39,
   title and banner Old Fenris (the client's "Serif" font 1302, self-hosted in main.css), acquisition text PT Serif italic 14.5 px */
.d4tt-chrome-skill .d4tt-content:has(> .d4tt-season) { padding: 3cqw 6.5cqw 7cqw; font-size: 3.825cqw; line-height: 1.39; }
.d4tt-season .stt-seasonbox { left: 50%; }
.d4tt-season .stt-title { font-family: 'OldFenris', var(--d4tt-body); font-size: 5.375cqw; line-height: 1.15; letter-spacing: .01em; color: #dcd7cd; }
.d4tt-season .stt-sub { font-size: 3.825cqw; line-height: 1.2; margin-top: 2.45cqw; }
.d4tt-season .stt-banner { display: flex; align-items: center; justify-content: center; box-sizing: border-box; height: 7.875cqw; padding: 0 2.4cqw; margin: 1.5cqw -.25cqw 0;
  font-size: 4.125cqw; line-height: 1; letter-spacing: .03em; color: #dcd9d3; }
.d4tt-season .stt-desc { line-height: 1.39; color: #b4aa9c; margin-top: 0; }
.d4tt-season .stt-divider.top { height: 3.75cqw; margin: 1.6cqw -.8cqw .6cqw; }
.d4tt-season .gt-c_important { color: #dcd9d3; font-weight: 400; } .d4tt-season .gt-b { font-weight: 400; }
.d4tt-season .gt-u { color: #e4e2e0; text-decoration: underline solid; text-underline-offset: .2em; }
.d4tt-season .stt-flavor { font-size: 3.625cqw; line-height: 1.38; }
/* ---- war plan perk (explorer warplans.css .wpt, game 212004/212009), measured on the explorer card: body 546 px = 100cqw, 1 px = .183cqw —
   round header ring 100 px (18.32cqw) with its centre on the frame's top edge (-7.33cqw), perk icon in its 82 px opening; title Old Fenris 29 px at 12.09cqw;
   "<◇>" divider 14 px, 18 px under the title; body 22 px / 1.4, padding 30 px each side; paragraphs 1.4em apart; 33 px under the last line */
.d4tt-chrome-skill:has(.d4tt-warplan) { margin-top: 44px; }
.d4tt-chrome-skill .d4tt-content:has(> .d4tt-warplan) { padding: 0 5.49cqw 6.04cqw; font-size: 4.03cqw; line-height: 1.4; color: #b4aa9c; }
.d4tt-warplan { position: relative; display: flow-root; }   /* flow-root: the title's top margin must not collapse through the root (it moved the ring down with it) */
.d4tt-warplan .wpt-head { position: absolute; left: 50%; top: -7.33cqw; width: 18.32cqw; height: 18.32cqw; transform: translateX(-50%); background: center / 100% 100% no-repeat; z-index: 5; pointer-events: none; }
.d4tt-warplan .wpt-head span { position: absolute; inset: 9%; border-radius: 50%; overflow: hidden; }
.d4tt-warplan .wpt-head img { position: absolute; left: -12%; top: -12%; width: 124%; height: 124%; max-width: none; object-fit: contain; }
.d4tt-warplan .wpt-title { text-align: center; font-family: 'OldFenris', var(--d4tt-body); font-size: 5.31cqw; line-height: 1.2; color: #dcd7cd; margin: 12.09cqw 0 1.47cqw; }
.d4tt-warplan .wpt-divider { height: 2.56cqw; margin: 3.3cqw 0 2.56cqw; background: center / 100% 100% no-repeat; }
.d4tt-warplan .wpt-desc { color: #b4aa9c; } .d4tt-warplan .wpt-desc + .wpt-desc { margin-top: 1.4em; }
.d4tt-warplan .gt-c_important { color: #dcd9d3; } .d4tt-warplan .gt-c_number { color: #d9a962; font-weight: 400; } .d4tt-warplan .gt-value { color: inherit; }
