.d4tt-chrome-item .d4tt-content .nongear .ot-banner { background: url(https://d4guides.gg/assets/img/ui/tooltip/section_header.webp) center / 100% 100% no-repeat; text-align: center; text-transform: uppercase; letter-spacing: .04em; padding: 4px 10px; margin: 8px 0 6px;
  color: #dcd9d3; font-family: 'OldFenris', var(--d4tt-head); }
