.d4tt-chrome-item .d4tt-content .nongear .ot-title.ot-title-wrap { hyphens: auto; overflow-wrap: anywhere; }
/* example roll picker below the tooltip (sigils, chronicle) */

/* ---------------- game look ---------------- */
/* header: title column 60 % of W, the 120 × 180 inventory art at its native size over the top-right frame (as gear), header ends with the divider
   at ≈ 30 % of W below the panel top even for one-line titles (212133 Iron Chunk, 211206 Flawless Diamond: divider at y ≈ 152 of 510) */
.d4tt-chrome-item .d4tt-content .nongear .tt-head.ot-head { display: block; position: static; margin: 0; padding: 0; background: none; min-height: 21cqw; }
