.d4tt-chrome-item .d4tt-content .nongear .it-footer .ft-exp .gt-icon-img { height: 1.34em !important; vertical-align: -.33em; margin-left: 0; }
.d4tt-chrome-item .d4tt-content .nongear .it-footer.ot-foot2 { margin: 0; }
.d4tt-chrome-item .d4tt-content .nongear .it-footer.ot-foot2 .gt-icon-img { height: .7em !important; vertical-align: -.02em; margin-left: .2em; }
/* seasonal leaf 12 × 15 px at W 512 (Marker_Season_Green_font, art 53 × 63 of its 100 px frame → frame 1.2 em of the footer size) */
.d4tt-chrome-item .d4tt-content .nongear .it-footer .ft-season .gt-icon-img { height: 1.2em !important; vertical-align: -.3em; margin-right: .25em; }
.d4tt-chrome-item .d4tt-content .nongear .ot-foot-pad { height: .4cqw; }

/* panels: unique and mythic non-gear items keep the neutral dark body of the rarity panel (211301 Terror ≈ #1e201d, 211500 Crux ≈ #181428) —
   no warm top tint and no violet glow (those match the gear screenshots only) */
.d4tt-chrome-item.d4tt-chrome-unique:has(.nongear) .d4tt-tint { background: none; }
.d4tt-chrome-item.d4tt-chrome-mythic:has(.nongear) .d4tt-glow { background: none; }

/* stacked game-look panels (paragon board card: board tooltip + socketed glyph, tooltip.js _appendChildTooltip) */
.item-tooltip:has(> .d4tt-stack) { background: none; border: 0; box-shadow: none; max-width: none; min-width: 0; padding: 0; border-radius: 0; }
.d4tt-stack { display: flex; flex-direction: column; align-items: flex-start; gap: 6px; width: 400px; max-width: min(100vw - 16px, 400px); }
.d4tt-stack > .d4tt-chrome { flex: none; }
.d4tt-stack__classic { background: #1A1B20; border: 1px solid #3f3f46; border-radius: 2px; box-shadow: 0 8px 24px rgba(0,0,0,.6); max-width: 100%; }
/* main.css sets img{display:block}: inline icons inside tooltip text stay inline */
.d4tt img.it-class-icon, .d4tt img.gt-icon-img, .d4tt img.affix-glyph { display: inline-block; }

/* ---- hint cards (explorer Tooltip kind "hint", views/Mercs.jsx SideCard 'merc' / 'text'; mercs.css .mw-tt): base panel (76 px corners × .5) +
   TooltipFrameLight = the ornate pieces at .3 (143 px → 43 px), both flush; padding 14/20 px; the text card sizes itself up to 440 px. Type sizes =
   .mw-tt proportions on the skill card's body size (22 u → 16.4 px) */
.d4tt-chrome-hint { width: max-content; max-width: min(100vw - 16px, 440px); container-type: normal; }
.d4tt-chrome-hint .d4tt-9s-base { --c: 38px; }
.d4tt-chrome-hint .d4tt-9s-light { --c: 43px; inset: 0; }
.d4tt-chrome-hint .d4tt-content { padding: 14px 20px; font-size: 16.4px; line-height: 1.35; color: #c4bdb2; }
.d4tt-hint .htt-title { font-family: 'OldFenris', Georgia, serif; font-size: 19.4px; line-height: 1.2; color: #dcd9d3; }
.d4tt-hint .htt-sub { color: #8a8378; font-size: 14.2px; margin-bottom: 6px; }
.d4tt-hint .htt-head { font-family: 'OldFenris', Georgia, serif; font-size: 16.4px; color: #b4aa9c; margin: 6px 0 2px; }
.d4tt-hint .htt-style { margin: 4px 0; }
.d4tt-hint .htt-style b { display: block; color: #dcd9d3; font-weight: 400; }
.d4tt-hint .htt-desc { color: #9a958c; margin-top: 6px; }
.d4tt-hint .gt-c_important { color: #ece8e0; } .d4tt-hint .gt-c_white { color: #fff; }

/* whole-pixel card width where the viewport squeezes it (see the 9-slice note at the top); after the width rules above so it wins */
@supports (width: round(1.5px, 1px)) {
  .d4tt-chrome { max-width: round(down, min(100vw - 16px, 400px), 1px); }
  .d4tt-chrome-generic:has(.d4tt-glyph) { max-width: round(down, min(100vw - 16px, 476px), 1px); }
  .d4tt-chrome-hint { max-width: round(down, min(100vw - 16px, 440px), 1px); }
}
